199	@DoNotMock("Use ClosingFuture.from(Futures.immediate*Future)")
200	@J2ktIncompatible
201	@GwtIncompatible // TODO(dpb): GWT compatibility.
202	public final class ClosingFuture<V extends @Nullable Object> {
203	
204	  private static final LazyLogger logger = new LazyLogger(ClosingFuture.class);
205	
206	  /**
207	   * An object that can capture objects to be closed later, when a {@link ClosingFuture} pipeline is
208	   * done.
209	   */
210	  public static final class DeferredCloser {
211	    @RetainedWith private final CloseableList list;
212	
213	    private DeferredCloser(CloseableList list) {
214	      this.list = list;
215	    }
216	
217	    /**
218	     * Captures an object to be closed when a {@link ClosingFuture} pipeline is done.
219	     *
220	     * <p>Be careful when targeting an older SDK than you are building against (most commonly when
221	     * building for Android): Ensure that any object you pass implements the interface not just in
222	     * your current SDK version but also at the oldest version you support. For example, <a
223	     * href="https://developer.android.com/sdk/api_diff/28/changes/android.media.MediaDrm#android.media.MediaDrm.close_added()">API
224	     * Level 28</a> is the first version in which {@code MediaDrm} is {@code AutoCloseable}. To
225	     * support older versions, pass a wrapper {@code AutoCloseable} with a method reference like
226	     * {@code mediaDrm::release}.
227	     *
228	     * @param closeable the object to be closed
229	     * @param closingExecutor the object will be closed on this executor
230	     * @return the first argument
231	     */
232	    @CanIgnoreReturnValue
233	    @ParametricNullness
234	    public <C extends @Nullable Object & @Nullable AutoCloseable> C eventuallyClose(
235	        @ParametricNullness C closeable, Executor closingExecutor) {
236	      checkNotNull(closingExecutor);
237	      if (closeable != null) {
238	        list.add(closeable, closingExecutor);
239	      }
240	      return closeable;
241	    }
242	  }
243	
244	  /**
245	   * An operation that computes a result.
246	   *
247	   * @param <V> the type of the result
248	   */
249	  @FunctionalInterface
250	  public interface ClosingCallable<V extends @Nullable Object> {
251	    /**
252	     * Computes a result, or throws an exception if unable to do so.
253	     *
254	     * <p>Any objects that are passed to {@link DeferredCloser#eventuallyClose(Object, Executor)
255	     * closer.eventuallyClose()} will be closed when the {@link ClosingFuture} pipeline is done (but
256	     * not before this method completes), even if this method throws or the pipeline is cancelled.
257	     */
258	    @ParametricNullness
259	    V call(DeferredCloser closer) throws Exception;
260	  }

