 38	/**
 39	 * Tests for {@link ClosingFuture} that exercise {@link
 40	 * ClosingFuture#finishToValueAndCloser(ValueAndCloserConsumer, Executor)}.
 41	 */
 42	@NullUnmarked
 43	@GwtIncompatible
 44	@J2ktIncompatible
 45	public class ClosingFutureFinishToValueAndCloserTest extends AbstractClosingFutureTest {
 46	  private final ExecutorService finishToValueAndCloserExecutor = newSingleThreadExecutor();
 47	  private volatile ValueAndCloser<?> valueAndCloser;
 48	
 49	  @Override
 50	  protected void tearDown() throws Exception {
 51	    super.tearDown();
 52	    assertWithMessage("finishToValueAndCloserExecutor was shut down")
 53	        .that(shutdownAndAwaitTermination(finishToValueAndCloserExecutor, 10, SECONDS))
 54	        .isTrue();
 55	  }
 56	
 57	  public void testFinishToValueAndCloser_throwsIfCalledTwice() {
 58	    ClosingFuture<Closeable> closingFuture =
 59	        ClosingFuture.submit(closer -> closer.eventuallyClose(mockCloseable, executor), executor);
 60	    closingFuture.finishToValueAndCloser(
 61	        new NoOpValueAndCloserConsumer<>(), finishToValueAndCloserExecutor);
 62	    assertThrows(
 63	        IllegalStateException.class,
 64	        () ->
 65	            closingFuture.finishToValueAndCloser(
 66	                new NoOpValueAndCloserConsumer<>(), finishToValueAndCloserExecutor));
 67	  }
 68	
 69	  public void testFinishToValueAndCloser_throwsAfterCallingFinishToFuture() {
 70	    ClosingFuture<Closeable> closingFuture =
 71	        ClosingFuture.submit(closer -> closer.eventuallyClose(mockCloseable, executor), executor);
 72	    FluentFuture<Closeable> unused = closingFuture.finishToFuture();
 73	    assertThrows(
 74	        IllegalStateException.class,
 75	        () ->
 76	            closingFuture.finishToValueAndCloser(
 77	                new NoOpValueAndCloserConsumer<>(), finishToValueAndCloserExecutor));
 78	  }
 79	
 80	  @Override
 81	  <T> T getFinalValue(ClosingFuture<T> closingFuture) throws ExecutionException {
 82	    return finishToValueAndCloser(closingFuture).get();
 83	  }
 84	
 85	  @Override
 86	  void assertFinallyFailsWithException(ClosingFuture<?> closingFuture) {
 87	    assertThatFutureFailsWithException(closingFuture.statusFuture());
 88	    ValueAndCloser<?> valueAndCloser = finishToValueAndCloser(closingFuture);
 89	    ExecutionException expected = assertThrows(ExecutionException.class, valueAndCloser::get);
 90	    assertThat(expected).hasCauseThat().isEqualTo(exception);
 91	    valueAndCloser.closeAsync();
 92	  }
 93	
 94	  @Override
 95	  void assertBecomesCanceled(ClosingFuture<?> closingFuture) {
 96	    assertThatFutureBecomesCancelled(closingFuture.statusFuture());
 97	  }
 98	
 99	  @Override
100	  void waitUntilClosed(ClosingFuture<?> closingFuture) {
101	    if (valueAndCloser != null) {
102	      valueAndCloser.closeAsync();
103	    }
104	    super.waitUntilClosed(closingFuture);
105	  }
106	
107	  @Override
108	  void cancelFinalStepAndWait(ClosingFuture<TestCloseable> closingFuture) {
109	    assertThat(closingFuture.cancel(false)).isTrue();
110	    ValueAndCloser<?> unused = finishToValueAndCloser(closingFuture);
111	    waitUntilClosed(closingFuture);
112	    futureCancelled.countDown();
113	  }
114	
115	  private <V> ValueAndCloser<V> finishToValueAndCloser(ClosingFuture<V> closingFuture) {
116	    CountDownLatch valueAndCloserSet = new CountDownLatch(1);
117	    closingFuture.finishToValueAndCloser(
118	        valueAndCloser -> {
119	          ClosingFutureFinishToValueAndCloserTest.this.valueAndCloser = valueAndCloser;
120	          valueAndCloserSet.countDown();
121	        },
122	        finishToValueAndCloserExecutor);
123	    assertWithMessage("valueAndCloser was set")
124	        .that(awaitUninterruptibly(valueAndCloserSet, 10, SECONDS))
125	        .isTrue();
126	    @SuppressWarnings("unchecked")
127	    ValueAndCloser<V> valueAndCloserWithType = (ValueAndCloser<V>) valueAndCloser;
128	    return valueAndCloserWithType;
129	  }
130	}

